1	// ivue newsletter Worker — entry point. Routing only; every behavior
2	// lives on a namespace-pattern class under src/modules/ (the invar
3	// conventions — see ../CONVENTIONS.md).
4	//
5	// The whole design is one invariant: at most one email per (subscriber,
6	// post), ever. The D1 `sends` table IS the invariant; the daily cron,
7	// /broadcast, and the dashboard's targeted send are three writers of the
8	// same ledger, so none can repeat what another already delivered.
9	//
10	//   POST /subscribe        {name, email, turnstileToken} — site form → D1
11	//   GET  /unsubscribe      ?email=&token=      — HMAC-signed one-click out
12	//   POST /broadcast        {slug}   (Bearer [redacted]) — send a post NOW
13	//   POST /drip             (Bearer [redacted]) — run a drip pass on demand
14	//   POST /postmark-webhook (Basic auth)         — Postmark suppression sync
15	//   *    /admin/*          (Bearer [redacted]) — the dashboard's JSON API
16	//   cron daily                                  — each due subscriber gets
17	//                                                 their oldest unsent post
18	//
19	// Everything else is served from the dashboard's static assets (the
20	// `assets` block in wrangler.jsonc) — the admin dashboard app itself.
21	
22	import { Http } from './modules/platform/Http';
23	import { PublicApi } from './modules/api/PublicApi';
24	import { AdminApi } from './modules/api/AdminApi';
25	import { Drip } from './modules/delivery/Drip';
26	import { Scheduler } from './modules/schedule/Scheduler';
27	
28	export default {
29	  async fetch(request, env, context): Promise<Response> {
30	    const url = new URL(request.url);
31	    if (request.method === 'OPTIONS')
32	      return Http.Class.withCors(new Response(null, { status: 204 }), env);
33	    try {
34	      if (url.pathname === '/subscribe' && request.method === 'POST')
35	        return Http.Class.withCors(
36	          await PublicApi.Class.subscribe(request, env, context),
37	          env,
38	        );
39	      if (url.pathname === '/unsubscribe' && request.method === 'GET')
40	        return PublicApi.Class.unsubscribe(url, env);
41	      if (url.pathname === '/broadcast' && request.method === 'POST')
42	        return PublicApi.Class.broadcast(request, env);
43	      if (url.pathname === '/drip' && request.method === 'POST')
44	        return PublicApi.Class.drip(request, env);
45	      if (url.pathname === '/postmark-webhook' && request.method === 'POST')
46	        return PublicApi.Class.postmarkWebhook(request, env);
47	      if (url.pathname.startsWith('/admin/'))
48	        return AdminApi.Class.handle(request, url, env);
49	      return Http.Class.notFound();
50	    } catch (error) {
51	      console.error(
52	        JSON.stringify({
53	          event: 'unhandled_error',
54	          path: url.pathname,
55	          error: String(error),
56	        }),
57	      );
58	      return Http.Class.withCors(
59	        Http.Class.json(
60	          { error: 'Something went wrong — try again in a minute.' },
61	          500,
62	        ),
63	        env,
64	      );
65	    }
66	  },
67	
68	  // Two crons: the daily drip at 13:00 UTC, and a 5-minute tick that
69	  // executes due scheduled jobs (broadcasts, X posts). The drip tick
70	  // drains the queue too — a job due at 13:00 should not wait.
71	  async scheduled(event, env, context): Promise<void> {
72	    if (event.cron === '0 13 * * *') context.waitUntil(Drip.Class.run(env));
73	    context.waitUntil(Scheduler.Class.runDue(env));
74	  },
75	} satisfies ExportedHandler<Env>;
