  const [cadenceDays, sendHourLocal, defaultTimezone] = await Promise.all([
    this.cadenceDays(env),
    this.sendHourLocal(env),
    this.defaultTimezone(env),
  ]);
  return { cadenceDays, sendHourLocal, defaultTimezone };
