import { describe, expect, it } from 'vitest';
import { Settings } from './Settings';
import { makeTestEnv } from '../../../test/TestDatabase';

describe('Settings', () => {
  it('falls back to the env drip clock when nothing is stored', async () => {
    const env = makeTestEnv();
    expect(await Settings.Class.dripSchedule(env)).toEqual({
      cadenceDays: 2,
      sendHourLocal: 9,
      defaultTimezone: 'America/Toronto',
    });
  });

  it('stored values override the env vars', async () => {
    const env = makeTestEnv();
    await Settings.Class.setCadenceDays(env, 3);
    await Settings.Class.setSendHourLocal(env, 18);
    await Settings.Class.setDefaultTimezone(env, 'Europe/Berlin');
    expect(await Settings.Class.dripSchedule(env)).toEqual({
      cadenceDays: 3,
      sendHourLocal: 18,
      defaultTimezone: 'Europe/Berlin',
    });
  });

  it('rejects out-of-range cadence, hour, and invalid timezones', async () => {
    const env = makeTestEnv();
    await expect(Settings.Class.setCadenceDays(env, 0)).rejects.toThrow();
    await expect(Settings.Class.setCadenceDays(env, 31)).rejects.toThrow();
    await expect(Settings.Class.setCadenceDays(env, 1.5)).rejects.toThrow();
    await expect(Settings.Class.setSendHourLocal(env, -1)).rejects.toThrow();
    await expect(Settings.Class.setSendHourLocal(env, 24)).rejects.toThrow();
    await expect(
      Settings.Class.setDefaultTimezone(env, 'Not/AZone'),
    ).rejects.toThrow();
  });

  it('a corrupted stored value falls back to the env drip clock', async () => {
    const env = makeTestEnv();
    await Settings.Class.write(env, Settings.Class.CADENCE_DAYS_KEY, 'junk');
    await Settings.Class.write(env, Settings.Class.SEND_HOUR_KEY, '99');
    await Settings.Class.write(
      env,
      Settings.Class.DEFAULT_TIMEZONE_KEY,
      'Broken/Zone',
    );
    expect(await Settings.Class.dripSchedule(env)).toEqual({
      cadenceDays: 2,
      sendHourLocal: 9,
      defaultTimezone: 'America/Toronto',
    });
  });

  it('per-list overrides layer over the defaults and clear back to inherit', async () => {
    const env = makeTestEnv();
    await Settings.Class.setListSchedule(env, 'vip', {
      cadenceDays: 1,
      sendHourLocal: 18,
    });
    expect(await Settings.Class.dripScheduleForList(env, 'vip')).toEqual({
      cadenceDays: 1,
      sendHourLocal: 18,
      defaultTimezone: 'America/Toronto',
    });
    // an un-overridden list inherits the defaults untouched
    expect(await Settings.Class.dripScheduleForList(env, 'newsletter')).toEqual(
      {
        cadenceDays: 2,
        sendHourLocal: 9,
        defaultTimezone: 'America/Toronto',
      },
    );
    // partial override: only the hour, cadence inherited
    await Settings.Class.setListSchedule(env, 'digest', {
      sendHourLocal: 7,
    });
    expect(await Settings.Class.dripScheduleForList(env, 'digest')).toEqual({
      cadenceDays: 2,
      sendHourLocal: 7,
      defaultTimezone: 'America/Toronto',
    });
    // clearing reverts to inherit
    await Settings.Class.setListSchedule(env, 'vip', {
      cadenceDays: null,
      sendHourLocal: null,
    });
    expect(await Settings.Class.listOverrides(env)).toEqual({
      digest: { sendHourLocal: 7 },
    });
    await expect(
      Settings.Class.setListSchedule(env, 'vip', { cadenceDays: 99 }),
    ).rejects.toThrow();
  });
});

import { describe, expect, it } from 'vitest';
import { LocalTime } from './LocalTime';

describe('LocalTime', () => {
  it('reads the local hour in a zone, DST included', () => {
    // 2026-01-05T14:00:00Z = 9am in Toronto (EST, UTC-5)
    const winter = Date.UTC(2026, 0, 5, 14) / 1000;
    expect(LocalTime.Class.hourAt(winter, 'America/Toronto')).toBe(9);
    // 2026-07-06T13:00:00Z = 9am in Toronto (EDT, UTC-4)
    const summer = Date.UTC(2026, 6, 6, 13) / 1000;
    expect(LocalTime.Class.hourAt(summer, 'America/Toronto')).toBe(9);
    expect(LocalTime.Class.hourAt(winter, 'UTC')).toBe(14);
    expect(LocalTime.Class.hourAt(winter, 'Asia/Tokyo')).toBe(23);
  });

  it('day numbers advance with the LOCAL calendar, not UTC', () => {
    // 2026-01-05T03:00:00Z is still Jan 4 in Toronto (10pm EST)
    const lateNight = Date.UTC(2026, 0, 5, 3) / 1000;
    expect(
      LocalTime.Class.dayNumberAt(lateNight, 'UTC') -
        LocalTime.Class.dayNumberAt(lateNight, 'America/Toronto'),
    ).toBe(1);
    // one local midnight apart = exactly one day number apart
    const monday = Date.UTC(2026, 0, 5, 14) / 1000;
    const tuesday = monday + 86_400;
    expect(
      LocalTime.Class.dayNumberAt(tuesday, 'America/Toronto') -
        LocalTime.Class.dayNumberAt(monday, 'America/Toronto'),
    ).toBe(1);
  });

  it('normalizeTimezone accepts IANA zones and rejects junk', () => {
    expect(LocalTime.Class.normalizeTimezone('America/Toronto')).toBe(
      'America/Toronto',
    );
    expect(LocalTime.Class.normalizeTimezone(' Europe/Berlin ')).toBe(
      'Europe/Berlin',
    );
    expect(LocalTime.Class.normalizeTimezone('Not/AZone')).toBe('');
    expect(LocalTime.Class.normalizeTimezone('')).toBe('');
    expect(LocalTime.Class.normalizeTimezone(null)).toBe('');
    expect(LocalTime.Class.normalizeTimezone(42)).toBe('');
  });
});

