106	function convertToLazyRef(
107	  proto: any,
108	  key: string,
109	  superKey: symbol,
110	  originalGetter: (this: any) => any,
111	  originalSetter: ((this: any, v: any) => any) | undefined,
112	) {
113	  // Optimization: Properties starting with $ are assumed singletons.
114	  const cacheWhole = key[0] === '$';
115	
116	  const newGetter = function (this: any) {
117	    const raw = resolveRaw(this);
118	
119	    // 1. Check cache
120	    if (superKey in raw) return raw[superKey];
121	
122	    // 2. Execute original
123	    const result = originalGetter.call(raw);
